from pathlib import Path
import json,pandas as pd
r=Path(__file__).resolve().parents[1];o=r/"phase32";m=pd.read_csv(o/"mechanism_summary.csv");s=pd.read_csv(o/"loso_summary.csv");p=pd.read_csv(o/"loso_people.csv");decision=json.loads((o/"advance_decisions.json").read_text());adv=[d for d in decision["decisions"] if d["advance"]];selected=s[s.policy.isin(["KEEP","WRITE","RESET","low_entropy_write","anchor_guard","future21","future36","future436","current436","future_hgb36","current_hgb36","future21_write_only","future36_write_only","future436_write_only","current436_write_only","future_confidence4_write_only"])];case=p[(p.lr==.001)&p.policy.isin(["WRITE","future436","current436"])]
html="""<!doctype html><html lang="zh"><meta charset="utf-8"><title>联合辅助模型的动态保留</title><style>body{font:15px/1.65 system-ui;max-width:1300px;margin:30px auto}td,th{padding:5px;border-bottom:1px solid #ccc}.box{background:#fff0d9;padding:16px}</style><h1>联合模型的动态参数保留诊断</h1><p>年轻来源、辅助权重0.01；4名源控制器，LR0.001/0.01，连续更新/每64窗口重置，共16条轨迹、2168次反事实探测。每20窗口比较保留、写入、重置对未来4窗口CE的影响。预测器按人留一，固定Ridge与浅树设置，包含同容量当前收益对照及动作限制对照。</p><div class="box">没有候选达到预先记录的推进条件。LR0.001的436特征未来预测器均值略高于总是写入，但只有2/4人正收益；其余未来候选均未超过全部简单规则。此轮不进入真实策略目标测试，不能声称学习式保留有效。</div><h2>轨迹内的写入与重置效用</h2><p>单位nats；正值降低未来CE。源状态重置的收益与新写入收益分开记录。oracle使用未来标签，是不可部署上界；不能把重叠脉冲收益相加成可实现在线F1。</p>"""+m.to_html(index=False,float_format=lambda x:f"{x:.7f}")+"<h2>按人留一：固定规则与学习规则</h2>"+selected.to_html(index=False,float_format=lambda x:f"{x:.7f}")+"<h2>唯一均值略胜候选的个人检查</h2>"+case.to_html(index=False,float_format=lambda x:f"{x:.7f}")+"""<p>436维观测包括当前预测、提议变化、参数偏移、当前源嵌入、因果历史及当前辅助损失；真实标签、是否正确、阶段稳定性和未来收益均不属于输入。12个未来扰动检查与48个历史前缀检查通过。每次反事实后准确恢复实际轨迹，16条实际轨迹指标独立复算。</p><a href="advance_decisions.json">预定推进规则与全部决定</a> · <a href="diagnostic_audit.json">诊断审计</a> · <a href="feature_causality_audit.json">特征因果性</a></html>""";(o/"report.html").write_text(html);print("Advancing candidates",len(adv))
